css:
* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent !important;
}

.carriage-widget {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent !important;
  color: #246975;

  font-family: Arial, Helvetica, sans-serif;

  user-select: none;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.carriage-stage {
  position: absolute;
  top: 0;
  left: 0;

  width: 1018px;
  height: 708px;

  transform-origin: top left;
  background: transparent !important;
}

.screen-header {
  position: absolute;
  top: 10px;
  left: 25px;
  right: 25px;
  height: 53px;
  overflow: hidden;
}

.screen-title {
  overflow: hidden;

  color: #0E5B67;
  font-size: 26px;
  font-weight: 700;
  line-height: 31px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.screen-subtitle {
  overflow: hidden;

  color: #728DA5;
  font-size: 14px;
  line-height: 19px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.screen-subtitle[hidden] {
  display: none;
}

.carriage-diagram {
  position: absolute;
  top: 70px;
  left: 25px;

  width: 968px;
  height: 569px;

  overflow: hidden;
  background: transparent;

  font-family: Arial, Helvetica, sans-serif;
}

.section-heading {
  fill: #246975;

  font-size: 22px;
  font-weight: 700;

  text-anchor: middle;
  text-decoration: underline;
}

.divider-line {
  fill: none;
  stroke: #8C9BA4;
  stroke-width: 3.5;
}

.mechanical-line,
.symbol-line,
.rail-line {
  fill: none;
  stroke: #4E4E4E;
  stroke-width: 1.2;

  stroke-linecap: square;
  stroke-linejoin: miter;
}

.indicator-line {
  fill: none;
  stroke: #61727C;
  stroke-width: 1.1;

  stroke-linecap: square;
  stroke-linejoin: miter;
}

.track-axis {
  fill: none;
  stroke: #788B97;
  stroke-width: 1.1;
  stroke-dasharray: 17 9;
}

.point-axis {
  fill: none;
  stroke: #788B97;
  stroke-width: 1.1;
}

.machine-body,
.roller-body {
  fill: #D7D8DB;
  stroke: #4E4E4E;
  stroke-width: 1.2;
}

.machine-inset {
  fill: #F4F6F8;
  stroke: #4E4E4E;
  stroke-width: 1.2;
}

.symbol-white,
.motor-node {
  fill: #FFFFFF;
  stroke: #4E4E4E;
  stroke-width: 1.1;
}

.symbol-mark {
  fill: #4E4E4E;
}

.sensor-tag,
.equipment-tag {
  fill: #405D6B;

  font-family: Arial, Helvetica, sans-serif;
  font-size: 12px;
  font-style: normal;
  font-weight: 700;
  font-variant: normal;

  letter-spacing: 0;
  text-anchor: middle;
  stroke: none;
}

.ground-hatch-area {
  fill: url(#carriage-ground-hatching);
  stroke: none;
}

.hatch-line {
  fill: none;
  stroke: #9BAAB4;
  stroke-width: 1;
}

/* La visibilidad cambia sin desplazar ningún elemento. */
.status-box {
  visibility: hidden;
}

.status-box.is-visible {
  visibility: visible;
}

.status-frame {
  stroke-width: 1.2;
}

.status-frame--blue {
  fill: #DDEBF7;
  stroke: #4B83A7;
}

.status-frame--yellow {
  fill: #FFF2B8;
  stroke: #CFB45C;
}

.status-text {
  font-family: Arial, Helvetica, sans-serif;
  font-style: normal;
  font-weight: 700;

  dominant-baseline: middle;
  stroke: none;
}

.status-text--blue {
  fill: #176A95;
  font-size: 16px;
  text-anchor: start;
}

.status-text--yellow {
  fill: #67571D;
  font-size: 15px;
  text-anchor: middle;
}

.screen-footer {
  position: absolute;
  top: 647px;
  left: 20px;
  right: 20px;
  height: 59px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  border-top: 1px solid #C8DAE5;
  background: transparent !important;
}

.visual-button {
  display: flex;
  width: 122px;
  height: 36px;

  align-items: center;
  justify-content: center;

  border: 1px solid #4B83A7;
  border-radius: 5px;

  background: linear-gradient(
    180deg,
    #FFFFFF,
    #EEF5F8
  );

  color: #1C5A6B;
  font-size: 13px;
  font-weight: 700;
  line-height: 1;
}

.brand-label {
  display: flex;
  height: 36px;
  align-items: center;

  color: #009999;
  font-size: 23px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.8px;
}

.carriage-stage .status-box rect[x="29"][y="4"],
.carriage-stage .status-box text[x="41"][y="20.5"] {
  transform: translateY(-4px);
}

