"use strict";

(function () {
  const SVG_NS = "http://www.w3.org/2000/svg";
  const BASE_WIDTH = 1018;
  const BASE_HEIGHT = 708;

  const DEFAULT_TITLE = "LÍNEA 3 / CARRO TRANSPORTADOR";
  const DEFAULT_SUBTITLE =
    "Vistas frontal y superior del carro transportador";

  const MESSAGES = [
    "No signal",
    "En Deposit. 1A",
    "En Deposit 1B",
    "En Deposit 2A",
    "En Deposit 2B",
    "En Deposit 3A",
    "En Deposit 3B",
    "En Deposit 4A",
    "En Deposit 4B",
    "En Prensa"
  ];

  const SENSORS = [
    { area: "front", tag: "-B621", x: 87,  y: 155, ty: 147 },
    { area: "front", tag: "-B622", x: 87,  y: 221, ty: 213 },
    { area: "front", tag: "-B623", x: 337, y: 150, ty: 130 },
    { area: "front", tag: "-B624", x: 337, y: 225, ty: 216 },

    { area: "front", tag: "-B723", x: 131, y: 455, ty: 452 },
    { area: "front", tag: "-B724", x: 181, y: 455, ty: 452 },
    { area: "front", tag: "-B725", x: 231, y: 455, ty: 452 },
    { area: "front", tag: "-B641", x: 311, y: 455, ty: 507 },
    { area: "front", tag: "-B642", x: 370, y: 455, ty: 507 },

    { area: "top", tag: "-B661", x: 710, y: 189, ty: 186 },
    { area: "top", tag: "-B662", x: 710, y: 236, ty: 234 },
    { area: "top", tag: "-B665", x: 648, y: 296, ty: 294 },
    { area: "top", tag: "-B663", x: 710, y: 296, ty: 294 },
    { area: "top", tag: "-B666", x: 648, y: 341, ty: 338 },
    { area: "top", tag: "-B664", x: 710, y: 341, ty: 338 },
    { area: "top", tag: "-B706", x: 902, y: 206, ty: 203 },

    { area: "top", tag: "-B682", x: 702, y: 445, ty: 438 },
    { area: "top", tag: "-B684", x: 752, y: 442, ty: 437 },
    { area: "top", tag: "-B686", x: 802, y: 442, ty: 437 },
    { area: "top", tag: "-B702", x: 852, y: 442, ty: 437 },
    { area: "top", tag: "-B704", x: 902, y: 442, ty: 437 },

    { area: "top", tag: "-B681", x: 682, y: 512, ty: 508 },
    { area: "top", tag: "-B683", x: 732, y: 512, ty: 508 },
    { area: "top", tag: "-B685", x: 782, y: 512, ty: 508 },
    { area: "top", tag: "-B701", x: 832, y: 512, ty: 508 },
    { area: "top", tag: "-B703", x: 882, y: 512, ty: 508 }
  ];

  const state = {
    name: "",
    principal: null,
    var1: null
  };

  let root = null;
  let stage = null;

  let blueBox = null;
  let blueText = null;
  let yellowBox = null;
  let yellowText = null;

  let currentName = null;
  let initialized = false;
  let receivedUpdate = false;

  function own(object, key) {
    return !!object &&
      Object.prototype.hasOwnProperty.call(object, key);
  }

  function readNumber(raw) {
    for (
      let depth = 0;
      depth < 4 &&
      raw !== null &&
      typeof raw === "object";
      depth += 1
    ) {
      if (!own(raw, "value")) return null;
      raw = raw.value;
    }

    if (typeof raw === "number") {
      return Number.isFinite(raw) ? raw : null;
    }

    if (
      typeof raw === "string" &&
      raw.trim() !== ""
    ) {
      const value = Number(raw.trim());

      return Number.isFinite(value)
        ? value
        : null;
    }

    return null;
  }

  function applyUpdate(widget) {
    if (
      !widget ||
      typeof widget !== "object"
    ) {
      return;
    }

    if (own(widget, "name")) {
      state.name =
        typeof widget.name === "string"
          ? widget.name
          : "";
    }

    // Variable principal: cuadro azul.
    if (own(widget, "value")) {
      state.principal =
        readNumber(widget.value);
    }

    // Variable adicional var1: cuadro amarillo.
    const variables = widget.vars;

    if (
      variables &&
      typeof variables === "object" &&
      !Array.isArray(variables) &&
      own(variables, "var1")
    ) {
      state.var1 =
        readNumber(variables.var1);
    }
  }

  function messageFor(value) {
    return Number.isInteger(value) &&
      value >= 1 &&
      value <= 9
      ? MESSAGES[value]
      : "No signal";
  }

  function updateBox(
    box,
    text,
    value,
    visible
  ) {
    text.textContent = messageFor(value);

    box.classList.toggle(
      "is-visible",
      visible
    );

    box.setAttribute(
      "aria-hidden",
      String(!visible)
    );
  }

  function updateStatuses() {
    if (
      !blueBox ||
      !blueText ||
      !yellowBox ||
      !yellowText
    ) {
      return;
    }

    /*
     * Condición exacta del cuadro azul:
     *
     * (principal <= 9) AND (principal <> 0)
     *
     * Un valor negativo también es visible,
     * mostrando "No signal".
     */
    const blueVisible =
      state.principal !== null &&
      state.principal <= 9 &&
      state.principal !== 0;

    /*
     * Condición exacta del cuadro amarillo:
     *
     * (var1 >= 1) AND (var1 <= 9)
     */
    const yellowVisible =
      state.var1 !== null &&
      state.var1 >= 1 &&
      state.var1 <= 9;

    updateBox(
      blueBox,
      blueText,
      state.principal,
      blueVisible
    );

    updateBox(
      yellowBox,
      yellowText,
      state.var1,
      yellowVisible
    );
  }

  function svgElement(
    tag,
    attributes,
    parent,
    content
  ) {
    const node =
      document.createElementNS(
        SVG_NS,
        tag
      );

    Object.keys(attributes).forEach(
      function (key) {
        node.setAttribute(
          key,
          String(attributes[key])
        );
      }
    );

    if (content !== undefined) {
      node.textContent = content;
    }

    parent.appendChild(node);
    return node;
  }

  function drawSensors() {
    const layers = {
      front: document.getElementById(
        "carriage-front-sensors"
      ),
      top: document.getElementById(
        "carriage-top-sensors"
      )
    };

    if (!layers.front || !layers.top) return;

    layers.front.replaceChildren();
    layers.top.replaceChildren();

    SENSORS.forEach(function (sensor) {
      const group = svgElement(
        "g",
        {},
        layers[sensor.area]
      );

      svgElement(
        "use",
        {
          href: "#carriage-sensor",
          x: sensor.x,
          y: sensor.y,
          width: 32,
          height: 32
        },
        group
      );

      svgElement(
        "text",
        {
          class: "sensor-tag",
          x: sensor.x + 16,
          y: sensor.ty
        },
        group,
        sensor.tag
      );
    });
  }

  function updateHeader() {
    if (!stage) return;

    const name = state.name.trim();

    if (name === currentName) return;
    currentName = name;

    const parts = name.split("//");

    const title =
      (parts[0] || "").trim() ||
      DEFAULT_TITLE;

    const subtitle =
      parts.length > 1
        ? parts.slice(1).join("//").trim()
        : DEFAULT_SUBTITLE;

    const titleNode =
      stage.querySelector(
        ".screen-title"
      );

    const subtitleNode =
      stage.querySelector(
        ".screen-subtitle"
      );

    titleNode.textContent = title;
    subtitleNode.textContent = subtitle;
    subtitleNode.hidden = subtitle === "";
  }

  function fitStage() {
    if (!root || !stage) return;

    const width = root.clientWidth;
    const height = root.clientHeight;

    if (
      width <= 0 ||
      height <= 0
    ) {
      return;
    }

    const scale = Math.min(
      width / BASE_WIDTH,
      height / BASE_HEIGHT
    );

    stage.style.left =
      (width - BASE_WIDTH * scale) / 2 +
      "px";

    stage.style.top =
      (height - BASE_HEIGHT * scale) / 2 +
      "px";

    stage.style.transform =
      "scale(" + scale + ")";
  }

  function render() {
    if (!initialized) return;

    updateHeader();
    updateStatuses();
  }

  /*
   * PSI CORE:
   *
   * w.value
   *   -> variable principal
   *   -> cuadro azul.
   *
   * w.vars.var1
   *   -> variable adicional var1
   *   -> cuadro amarillo.
   *
   * Las actualizaciones parciales
   * conservan el estado del otro cuadro.
   */
  window.onWidgetUpdate = function (widget) {
    receivedUpdate = true;

    applyUpdate(widget);
    render();
  };

  function initialize() {
    if (initialized) return;

    root = document.querySelector(
      ".carriage-widget"
    );

    stage = document.querySelector(
      ".carriage-stage"
    );

    blueBox = document.getElementById(
      "carriage-blue-box"
    );

    blueText = document.getElementById(
      "carriage-blue-text"
    );

    yellowBox = document.getElementById(
      "carriage-yellow-box"
    );

    yellowText = document.getElementById(
      "carriage-yellow-text"
    );

    if (
      !root ||
      !stage ||
      !blueBox ||
      !blueText ||
      !yellowBox ||
      !yellowText
    ) {
      return;
    }

    drawSensors();

    if (!receivedUpdate) {
      applyUpdate(
        window.WIDGET || null
      );
    }

    initialized = true;

    render();
    fitStage();

    if (
      typeof ResizeObserver !==
      "undefined"
    ) {
      new ResizeObserver(
        fitStage
      ).observe(root);
    } else {
      window.addEventListener(
        "resize",
        fitStage
      );
    }
  }

  if (
    document.readyState ===
    "loading"
  ) {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
